<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    let renderVersion = 0;

    async function api(path, options) {
      const response = await fetch(path, options);
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'Unable to load data');
      return body;
    }

    function showAlert(message) {
      const alert = app.querySelector('[role="alert"]');
      alert.textContent = message;
      alert.hidden = !message;
    }

    function navigate(path) {
      history.pushState({}, '', path);
      render();
    }

    async function render() {
      const version = ++renderVersion;
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        app.innerHTML = '<h1>Loading project…</h1><button type="button">Projects</button><div role="alert" hidden></div>';
        app.querySelector('button').onclick = () => navigate('/');
        try {
          const project = await api('/api/projects/' + match[1]);
          if (version !== renderVersion) return;
          app.querySelector('h1').textContent = project.name;
          document.title = project.name + ' · Workboard';
          if (project.archived) {
            const notice = document.createElement('p');
            notice.textContent = 'Archived project';
            app.append(notice);
          }
          const renameForm = document.createElement('form');
          renameForm.className = 'task-controls';
          renameForm.innerHTML = `
            <label for="new-project-name">New project name</label>
            <div class="fields"><input id="new-project-name" name="name" type="text"><button type="submit">Rename project</button></div>`;
          const renameInput = renameForm.querySelector('input');
          const renameButton = renameForm.querySelector('button');
          renameInput.disabled = Boolean(project.archived);
          renameButton.disabled = Boolean(project.archived);
          renameForm.onsubmit = async event => {
            event.preventDefault();
            if (project.archived) return;
            const name = renameInput.value.trim();
            if (!name) return showAlert('Project name is required');
            renameButton.disabled = true;
            showAlert('');
            try {
              const saved = await api('/api/projects/' + project.id, {
                method: 'PATCH', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name })
              });
              Object.assign(project, saved);
              if (version !== renderVersion) return;
              app.querySelector('h1').textContent = project.name;
              document.title = project.name + ' · Workboard';
              renameInput.value = '';
              renameInput.focus();
            } catch (error) {
              if (version === renderVersion) showAlert(error.message);
            } finally {
              renameButton.disabled = Boolean(project.archived);
            }
          };
          app.append(renameForm);
          const controls = document.createElement('div');
          controls.className = 'task-controls';
          controls.innerHTML = `
            <form>
              <label for="task-title">Task title</label>
              <div class="fields"><input id="task-title" name="title" type="text"><button type="submit">Create task</button></div>
            </form>
            <div class="task-filter">
              <label for="task-filter">Task filter</label>
              <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
            </div>
            <div id="tasks"></div>`;
          app.append(controls);
          const form = controls.querySelector('form');
          form.querySelector('button').disabled = Boolean(project.archived);
          const input = controls.querySelector('#task-title');
          const filter = controls.querySelector('select');
          const taskList = controls.querySelector('#tasks');
          const tasksPath = '/api/projects/' + project.id + '/tasks';
          let tasks = [];
          function drawTasks() {
            taskList.replaceChildren();
            for (const task of tasks) {
              if (filter.value === 'Open' && task.completed) continue;
              if (filter.value === 'Completed' && !task.completed) continue;
              const row = document.createElement('div');
              row.className = 'task-row';
              row.dataset.testid = 'task-row';
              const label = document.createElement('label');
              const checkbox = document.createElement('input');
              checkbox.type = 'checkbox';
              checkbox.checked = task.completed;
              checkbox.disabled = Boolean(project.archived);
              checkbox.setAttribute('aria-label', 'Complete ' + task.title);
              const title = document.createElement('span');
              title.textContent = task.title;
              label.append(checkbox, title);
              row.append(label);
              taskList.append(row);
              checkbox.onchange = async () => {
                checkbox.disabled = true;
                showAlert('');
                try {
                  const saved = await api(tasksPath + '/' + task.id, {
                    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ completed: checkbox.checked })
                  });
                  task.completed = saved.completed;
                  drawTasks();
                } catch (error) {
                  checkbox.checked = task.completed;
                  if (version === renderVersion) showAlert(error.message);
                } finally {
                  checkbox.disabled = Boolean(project.archived);
                }
              };
            }
          }
          filter.onchange = drawTasks;
          const loaded = api(tasksPath).then(items => {
            tasks = items;
            drawTasks();
          });
          loaded.catch(error => { if (version === renderVersion) showAlert(error.message); });
          form.onsubmit = async event => {
            event.preventDefault();
            if (project.archived) return;
            const title = input.value.trim();
            if (!title) return showAlert('Task title is required');
            const button = form.querySelector('button');
            button.disabled = true;
            showAlert('');
            try {
              await loaded;
              const task = await api(tasksPath, {
                method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
              });
              tasks.push(task);
              drawTasks();
              input.value = '';
              input.focus();
            } catch (error) {
              if (version === renderVersion) showAlert(error.message);
            } finally {
              button.disabled = Boolean(project.archived);
            }
          };
        } catch (error) {
          if (version === renderVersion) showAlert(error.message);
        }
        return;
      }
      document.title = 'Workboard';
      app.innerHTML = `
        <h1>Workboard</h1>
        <form>
          <label for="project-name">Project name</label>
          <div class="fields"><input id="project-name" name="name" type="text"><button type="submit">Create project</button></div>
        </form>
        <div role="alert" hidden></div>
        <div class="task-filter">
          <label for="project-filter">Project filter</label>
          <select id="project-filter"><option>Active</option><option>Archived</option></select>
        </div>
        <div id="projects"></div>`;
      const form = app.querySelector('form');
      const input = app.querySelector('input');
      const projects = app.querySelector('#projects');
      const filter = app.querySelector('#project-filter');
      let items = [];
      function drawProjects() {
        projects.replaceChildren();
        items.filter(project => Boolean(project.archived) === (filter.value === 'Archived')).forEach(addRow);
      }
      filter.onchange = drawProjects;
      function addRow(project) {
        const row = document.createElement('div');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const summary = document.createElement('span');
        summary.className = 'project-summary';
        summary.dataset.testid = 'project-summary';
        summary.textContent = project.completed_count + '/' + project.total_count + ' completed';
        const details = document.createElement('div');
        details.append(name, summary);
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Open project';
        button.onclick = () => navigate('/projects/' + project.id);
        const archive = document.createElement('button');
        archive.type = 'button';
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.onclick = async () => {
          archive.disabled = true;
          showAlert('');
          try {
            const saved = await api('/api/projects/' + project.id, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ archived: !project.archived })
            });
            Object.assign(project, saved);
            drawProjects();
          } catch (error) {
            if (version === renderVersion) showAlert(error.message);
          } finally {
            archive.disabled = false;
          }
        };
        const actions = document.createElement('div');
        actions.className = 'project-actions';
        actions.append(button, archive);
        row.append(details, actions);
        projects.append(row);
      }
      // Keep initial loading ahead of creation so each row appears exactly once.
      const loaded = api('/api/projects').then(loadedItems => {
        items = loadedItems;
        drawProjects();
      });
      loaded.catch(error => { if (version === renderVersion) showAlert(error.message); });
      form.onsubmit = async event => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) return showAlert('Project name is required');
        const button = form.querySelector('button');
        button.disabled = true;
        showAlert('');
        try {
          await loaded;
          const project = await api('/api/projects', {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
          });
          items.push(project);
          drawProjects();
          input.value = '';
          input.focus();
        } catch (error) {
          showAlert(error.message);
        } finally {
          button.disabled = false;
        }
      };
    }
    window.addEventListener('popstate', render);
    render();
  </script>
</body>
</html>
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import { DatabaseSync } from 'node:sqlite';

test('projects and tasks validate, migrate, rename, archive, restore, and persist across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const probe = net.createServer();
  probe.listen(0, '127.0.0.1');
  await once(probe, 'listening');
  const port = probe.address().port;
  await new Promise(resolve => probe.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  let output = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'nested', 'projects.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe']
    });
    child.stdout.on('data', chunk => { output += chunk; });
    child.stderr.on('data', chunk => { output += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      try {
        const response = await fetch(base + '/health');
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch {
        if (child.exitCode !== null) throw new Error(output);
        await new Promise(resolve => setTimeout(resolve, 30));
      }
    }
    throw new Error('Server did not become healthy: ' + output);
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  async function create(name) {
    return fetch(base + '/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
  }
  async function createTask(projectId, title) {
    return fetch(`${base}/api/projects/${projectId}/tasks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
    });
  }
  async function complete(projectId, taskId, completed) {
    return fetch(`${base}/api/projects/${projectId}/tasks/${taskId}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed })
    });
  }
  async function archive(projectId, archived) {
    return fetch(`${base}/api/projects/${projectId}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived })
    });
  }
  async function rename(projectId, name) {
    return fetch(`${base}/api/projects/${projectId}`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
  }
  async function tasks(projectId) {
    return (await fetch(`${base}/api/projects/${projectId}/tasks`)).json();
  }
  try {
    await start();
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), []);
    for (const name of ['', '  \n\t ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    assert.equal(first.archived, 0);
    assert.equal(first.total_count, 0);
    assert.equal(first.completed_count, 0);
    const second = await (await create('Second <project>')).json();
    assert.notEqual(first.id, second.id);
    const expected = [first, second];
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), expected);
    for (const title of ['', '  \n\t ']) {
      const response = await createTask(first.id, title);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await tasks(first.id), []);
    const taskResponse = await createTask(first.id, '  First task  ');
    assert.equal(taskResponse.status, 201);
    const firstTask = await taskResponse.json();
    assert.equal(firstTask.title, 'First task');
    assert.equal(firstTask.completed, false);
    const secondTask = await (await createTask(first.id, 'Second <task>')).json();
    const otherTask = await (await createTask(second.id, 'Other project task')).json();
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.deepEqual(await tasks(second.id), [otherTask]);
    assert.equal((await complete(second.id, firstTask.id, true)).status, 404);
    assert.equal((await complete(first.id, firstTask.id, 'true')).status, 400);
    assert.equal((await complete(first.id, firstTask.id, true)).status, 200);
    firstTask.completed = true;
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    assert.equal((await createTask(99999, 'Missing project')).status, 404);
    first.total_count = 2;
    first.completed_count = 1;
    second.total_count = 1;
    for (const name of ['', '  \n\t ', null, 123]) {
      const response = await rename(first.id, name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
      assert.deepEqual(await (await fetch(base + '/api/projects/' + first.id)).json(), first);
    }
    assert.equal((await rename(99999, 'Missing project')).status, 404);
    const renamedResponse = await rename(first.id, '  Renamed <project> \n ');
    assert.equal(renamedResponse.status, 200);
    first.name = 'Renamed <project>';
    assert.deepEqual(await renamedResponse.json(), first);
    assert.deepEqual(await (await fetch(base + '/api/projects')).json(), expected);
    assert.deepEqual(await tasks(first.id), [firstTask, secondTask]);
    await stop();
    // Simulate a Task 002 database containing existing projects and completed tasks.
    const legacy = new DatabaseSync(join(directory, 'nested', 'projects.sqlite'));
    legacy.exec('ALTER TABLE projects DROP COLUMN archived');
    legacy.close();
